def farthestAfterJumps(nums, k):
    n = len(nums)
    reach = 0
    i = 0
    for _ in range(k):
        nxt = reach
        while i <= reach:
            if i + nums[i] > nxt:
                nxt = i + nums[i]
            i += 1
        if nxt > n - 1:
            nxt = n - 1
        if nxt == reach:
            break
        reach = nxt
    return reach
